const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const D=__dirname,REPO=path.resolve(D,'../../..');const{setup:base}=require('../provider-snapshot-retention/baseline-harness.cjs');
const read=f=>fs.readFileSync(f.startsWith('candidate/')?path.join(REPO,f.slice(10)):path.join(D,f),'utf8');
const rawInstall=read('candidate/supabase/migrations/20261015081659_provider_snapshot_inactive_cron.sql');
const rawRollback=read('rollback.sql');
const boundary=/-- BEGIN native cron environment guard[^\n]*\n[\s\S]*?-- END native cron environment guard\./g;
function portable(sql){assert.equal([...sql.matchAll(boundary)].length,1);return sql.replace(boundary,"if current_setting('test.cron_runtime',true)is distinct from'libpq-1.6.4-mock'then raise exception 'mock_cron_runtime_denied';end if;");}
const install=portable(rawInstall),rollback=portable(rawRollback),jobs=JSON.parse(read('jobs.json'));
const scalar=async(db,q,p=[])=>Object.values((await db.query(q,p)).rows[0]||{})[0];
const mock=`create schema cron;
create table cron.job(jobid bigint generated always as identity primary key,jobname text not null,schedule text not null,command text not null,database text not null default current_database(),username text not null default current_user,active boolean not null default true,unique(jobname,username));
create table cron.job_run_details(runid bigint generated always as identity primary key,jobid bigint,database text,username text,status text,end_time timestamptz);
create function cron.schedule(job_name text,schedule text,command text)returns bigint language plpgsql as $$declare id bigint;begin
if current_setting('test.fail_schedule',true)=job_name then raise exception 'mock_schedule_failure';end if;
if current_setting('test.serialize_schedule',true)=job_name then raise exception using errcode='40001',message='could not serialize access due to concurrent update';end if;
insert into cron.job(jobname,schedule,command)values(job_name,schedule,command)on conflict(jobname,username)do update set schedule=excluded.schedule,command=excluded.command returning jobid into id;return id;end;$$;
create function cron.alter_job(job_id bigint,schedule text default null,command text default null,database text default null,username text default null,active boolean default null)returns void language plpgsql as $$begin update cron.job j set active=coalesce(alter_job.active,j.active)where j.jobid=job_id;end;$$;
create function cron.unschedule(id bigint)returns boolean language plpgsql as $$begin delete from cron.job where jobid=id;return found;end;$$;
select set_config('test.cron_runtime','libpq-1.6.4-mock',false);`;
async function setup(){const db=await base({protocol:false});await db.exec(read('candidate/supabase/migrations/20261015081222_provider_snapshot_tiered_retention.sql'));await db.exec(mock);return db;}
async function rejects(db,sql,re){await assert.rejects(()=>db.exec(sql),re);await db.exec('rollback');}
async function addTarget(db,name='CRON_SYNTHETIC'){await db.query("insert into public.ar_config_targets values('AR','IN',$1,'INR','印度','Asia/Kolkata')",[name]);await db.query("insert into public.dashboard_platform_team_map values('AR','IN',$1,$1,'M8','IN','印度',true)",[name]);const t=await scalar(db,'select to_jsonb(t)from private.provider_snapshot_native_catalog()t where source_name=$1',[name]);await db.query('select private.provider_snapshot_register_target($1)',[t]);return t;}
const dispatch=(db,time)=>scalar(db,'select private.provider_snapshot_dispatch($1,600)',[time]);
async function noOldDates(db,observed){const r=await scalar(db,'select jsonb_agg(target order by platform_id)from private.provider_snapshot_targets where enabled');await db.query("insert into private.provider_snapshot_cohorts(lane,local_date,cutoff,supplement_pass,roster_token,targets,status) select'closed',($1::timestamptz at time zone'Asia/Kolkata')::date-n,((($1::timestamptz at time zone'Asia/Kolkata')::date-n+1)::timestamp at time zone'Asia/Kolkata'),p,md5($2::jsonb::text),$2,'ready'from generate_series(1,2)n cross join generate_series(0,2)p",[observed,r]);}
test('actual PG guarded install remains inactive; replay/rollback preserve data and catch-up audit',async()=>{const db=await setup();try{const target=await addTarget(db,'TOKEN_INSTALL');const token=await scalar(db,'select private.provider_snapshot_dependency_token($1)',[target]);await db.exec(install);assert.equal(await scalar(db,'select private.provider_snapshot_dependency_token($1)',[target]),token);assert.deepEqual((await db.query('select jobname,schedule,command,active from cron.job order by jobname')).rows,[...jobs].sort((a,b)=>a.jobname.localeCompare(b.jobname)));await db.exec(install);assert.equal(await scalar(db,'select count(*)::int from cron.job'),3);await db.exec("insert into private.provider_schedule_catchup_audit values(gen_random_uuid(),'2026-10-10','2026-10-11T18:30:00Z',2,'{0,1}','2026-10-14T00:00:00Z')");await db.exec(rollback);await db.exec(rollback);assert.equal(await scalar(db,'select private.provider_snapshot_dependency_token($1)',[target]),token);assert.equal(await scalar(db,'select count(*)::int from cron.job'),0);assert.equal(await scalar(db,'select count(*)::int from private.provider_schedule_catchup_audit'),1);assert.equal(await scalar(db,"select md5(prosrc)from pg_proc where oid='private.provider_snapshot_dispatch(timestamptz,integer)'::regprocedure"),'7d123f5838e7c67ccf374ccf17a88e93');await db.exec(install);for(const role of['anon','authenticated','service_role'])assert.equal(await scalar(db,"select has_table_privilege($1,'private.provider_schedule_catchup_audit','SELECT')",[role]),false);}finally{await db.close()}});
test('name collision, partial/active installation, runtime mismatch and midway failure all fail closed atomically',async()=>{const db=await setup();try{await rejects(db,rawInstall,/snapshot_cron_runtime_unsupported/);await db.exec("select cron.schedule('provider-snapshot-worker-v1','5 seconds','select 1')");await rejects(db,install,/snapshot_cron_job_drift/);assert.equal(await scalar(db,'select command from cron.job'),'select 1');await db.exec('delete from cron.job');await db.exec("select set_config('test.fail_schedule','provider-snapshot-dispatch-v1',false)");await rejects(db,install,/mock_schedule_failure/);assert.equal(await scalar(db,'select count(*)::int from cron.job'),0);assert.equal(await scalar(db,"select to_regclass('private.provider_schedule_catchup_audit')::text"),null);await db.exec("select set_config('test.fail_schedule','',false)");await db.exec(install);await db.exec('update cron.job set active=true');await rejects(db,install,/snapshot_cron_job_drift/);await rejects(db,rollback,/snapshot_cron_job_drift/);assert.equal(await scalar(db,'select count(*)::int from cron.job where active'),3);}finally{await db.close()}});
test('metadata or live lease drift prevents installer/rollback from changing jobs',async()=>{const db=await setup();try{await db.exec('grant execute on function private.provider_snapshot_dispatch(timestamptz,integer)to authenticated');await rejects(db,install,/before_function_drift/);await db.exec('revoke execute on function private.provider_snapshot_dispatch(timestamptz,integer)from authenticated');await db.exec(install);await db.exec('alter table private.provider_schedule_catchup_audit disable row level security');await rejects(db,rollback,/snapshot_cron_audit_drift/);await db.exec('alter table private.provider_schedule_catchup_audit enable row level security');await addTarget(db);const c=await dispatch(db,'2026-10-13T06:37:00Z');assert.equal(c.jobs,5);await db.exec("set statement_timeout='3s'");await scalar(db,"select private.provider_snapshot_prepare_claim('lease-test')");await rejects(db,rollback,/snapshot_cron_active_lease/);assert.equal(await scalar(db,'select count(*)::int from cron.job'),3);}finally{await db.close()}});
test('current deadline stays cutoff + 30min, prior window uses the same progress, and pending cutoffs coalesce',async()=>{const db=await setup();try{await db.exec(install);await addTarget(db);const when='2026-10-13T06:37:00Z';await noOldDates(db,when);await db.exec("set timezone='Pacific/Kiritimati'");const c=await dispatch(db,when);assert.equal(c.lane,'current');assert.equal(c.cutoff,'2026-10-13T06:30:00.000000Z');assert.equal(await scalar(db,"select bool_and(next_due_at=($1::timestamptz+interval'30minutes'))from private.provider_snapshot_jobs",[c.cutoff]),true);const windows=(await db.query('select distinct window_to-window_from duration from private.provider_snapshot_jobs')).rows;assert.equal(windows.length,1);const again=await dispatch(db,'2026-10-13T07:02:00Z');assert.equal(again.cohortId,c.cohortId);assert.equal(again.pendingCutoff,'2026-10-13T07:00:00.000000Z');assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_jobs'),5);assert.equal(await scalar(db,"select bool_and(next_due_at='2026-10-13T07:00:00Z')from private.provider_snapshot_jobs"),true);}finally{await db.close()}});
test('first late startup skips unexecuted closed passes with durable audit, alternating current and catch-up work',async()=>{const db=await setup();try{await db.exec(install);await addTarget(db);await db.exec("update private.provider_snapshot_schedule_state set last_lane='current'");const c=await dispatch(db,'2026-10-13T06:37:00Z');assert.equal(c.lane,'closed');assert.equal(c.supplementPass,2);assert.deepEqual(c.coalescedPasses,[0,1]);assert.equal(await scalar(db,'select bool_and(next_due_at is null)from private.provider_snapshot_jobs'),true);assert.equal(await scalar(db,"select count(*)::int from private.provider_snapshot_cohorts where lane='closed'and supplement_pass in(0,1)"),0);const audit=(await db.query('select supplement_pass,coalesced_passes from private.provider_schedule_catchup_audit')).rows;assert.deepEqual(audit,[{supplement_pass:2,coalesced_passes:[0,1]}]);await db.query("update private.provider_snapshot_cohorts set status='ready'where id=$1",[c.cohortId]);const next=await dispatch(db,'2026-10-13T06:38:00Z');assert.equal(next.lane,'current');await db.query("update private.provider_snapshot_cohorts set status='ready'where id=$1",[next.cohortId]);const later=await dispatch(db,'2026-10-13T06:39:00Z');assert.equal(later.lane,'closed');assert.equal(later.supplementPass,1);assert.deepEqual(later.coalescedPasses,[0]);assert.equal(await scalar(db,'select bool_and(next_due_at> $1::timestamptz)from private.provider_snapshot_jobs where id in(select job_id from private.provider_snapshot_cohort_jobs where cohort_id=$2)', ['2026-10-13T06:39:00Z',later.cohortId]),true);}finally{await db.close()}});
test('already completed primary is not called skipped; failed supplement remains parked across restart',async()=>{const db=await setup();try{await db.exec(install);await addTarget(db);const r=await scalar(db,'select jsonb_agg(target order by platform_id)from private.provider_snapshot_targets');await db.query("insert into private.provider_snapshot_cohorts(lane,local_date,cutoff,supplement_pass,roster_token,targets,status)values('closed','2026-10-11','2026-10-11T18:30:00Z',0,md5($1::jsonb::text),$1,'ready')",[r]);await db.exec("update private.provider_snapshot_schedule_state set last_lane='current'");const late=await dispatch(db,'2026-10-13T06:37:00Z');assert.equal(late.supplementPass,2);assert.deepEqual(late.coalescedPasses,[1]);await db.query("update private.provider_snapshot_cohorts set status='failed'where id=$1",[late.cohortId]);await db.query("insert into private.provider_snapshot_cohorts(lane,local_date,cutoff,supplement_pass,roster_token,targets,status)values('closed','2026-10-12','2026-10-12T18:30:00Z',1,md5($1::jsonb::text),$1,'failed')",[r]);const resumed=await dispatch(db,'2026-10-13T06:38:00Z');assert.equal(resumed.lane,'current');assert.equal(await scalar(db,"select count(*)::int from private.provider_snapshot_cohorts where lane='closed'"),3);assert.equal(await scalar(db,'select count(*)::int from private.provider_schedule_catchup_audit'),1);}finally{await db.close()}});
test('successful own run logs retain 24h, failed logs retain 7d, bounded cleanup cannot touch other jobs',async()=>{const db=await setup();try{await db.exec(install);await db.exec("select cron.schedule('unrelated','1 second','select 1')");await db.exec("insert into cron.job_run_details(jobid,database,username,status,end_time)select jobid,current_database(),current_user,'succeeded',clock_timestamp()-interval'2days'from cron.job cross join generate_series(1,1005)where jobname='provider-snapshot-worker-v1'");await db.exec("insert into cron.job_run_details(jobid,database,username,status,end_time)select jobid,current_database(),current_user,'succeeded',clock_timestamp()-interval'2days'from cron.job where jobname='unrelated'");await db.exec("insert into cron.job_run_details(jobid,database,username,status,end_time)select jobid,current_database(),current_user,status,clock_timestamp()-age from cron.job cross join(values('failed',interval'2days'),('failed',interval'8days'),('succeeded',interval'1hour'),('running',interval'2days'))v(status,age)where jobname='provider-snapshot-worker-v1'");await db.exec(read('maintenance-command.sql'));assert.equal(await scalar(db,'select count(*)::int from cron.job_run_details'),10);await db.exec(read('maintenance-command.sql'));assert.equal(await scalar(db,'select count(*)::int from cron.job_run_details'),4);assert.equal(await scalar(db,"select count(*)::int from cron.job_run_details d join cron.job j on j.jobid=d.jobid where j.jobname='unrelated'"),1);assert.equal(await scalar(db,"select count(*)::int from cron.job_run_details where status='failed'"),1);}finally{await db.close()}});
test('log cleanup remains committed if later retention maintenance fails',async()=>{const db=await setup();try{await db.exec(install);await db.exec("insert into cron.job_run_details(jobid,database,username,status,end_time)select jobid,current_database(),current_user,'succeeded',clock_timestamp()-interval'2days'from cron.job");await db.exec("create or replace function private.provider_snapshot_maintain(p_artifact_limit integer default 100)returns jsonb language plpgsql volatile security invoker set search_path=''as $$begin raise exception 'synthetic_maintenance_failed';end;$$");await rejects(db,read('maintenance-command.sql'),/synthetic_maintenance_failed/);assert.equal(await scalar(db,'select count(*)::int from cron.job_run_details'),0);}finally{await db.close()}});
test('a complete 18-target cohort evaluates dependency token once per target, reuses it for both readiness checks',async()=>{const db=await setup();try{await db.exec(install);for(let i=0;i<18;i++)await addTarget(db,'COUNT_'+i);await db.exec("create sequence private.test_dependency_calls;alter function private.provider_snapshot_dependency_token(jsonb)rename to test_dependency_original;create function private.provider_snapshot_dependency_token(p_target jsonb)returns text language plpgsql stable security invoker set search_path=''as $$begin perform nextval('private.test_dependency_calls');return private.test_dependency_original(p_target);end;$$");const when='2026-10-13T06:37:00Z';await noOldDates(db,when);const c=await dispatch(db,when);assert.equal(c.jobs,90);await db.exec("insert into private.provider_snapshot_artifacts(job_id,run_id,fence,revision,dependency_token,payload,payload_hash,stored_bytes,provenance,next_due_at)select id,gen_random_uuid(),fence,revision,dependency_token,'{}','synthetic',2,'{}',next_due_at from private.provider_snapshot_jobs;insert into private.provider_snapshot_heads(job_id,snapshot_id)select job_id,id from private.provider_snapshot_artifacts;update private.provider_snapshot_jobs set status='ready';select setval('private.test_dependency_calls',1,false)");const done=await dispatch(db,when);assert.equal(done.status,'idle');assert.equal(Number(await scalar(db,'select last_value from private.test_dependency_calls')),18);assert.equal(await scalar(db,'select status from private.provider_snapshot_cohorts where id=$1',[c.cohortId]),'ready');}finally{await db.close()}});
test('same-session worker commits one claim and persists an actual source-contract failure without an immediate retry',async()=>{const db=await setup();try{await db.exec(install);const t=await addTarget(db);const q={action:'aggregate',view:'providers',platformId:t.id,startAt:'2026-10-10T18:30:00.000000Z',endAt:'2026-10-11T18:30:00.000000Z',direction:'charge',status:'all',currency:'INR',offset:0,limit:20};await db.query("select private.provider_snapshot_enqueue($1,$2,'orders')",[t,q]);
// The existing foundation fixture has metadata-only source tables, not fabricated source DTOs.
await db.exec(read('worker-command.sql'));assert.deepEqual((await db.query("select status,attempts,last_error_code from private.provider_snapshot_jobs")).rows,[{status:'failed',attempts:1,last_error_code:'compute_failed'}]);assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_heads'),0);await db.exec(read('worker-command.sql'));assert.equal(await scalar(db,'select attempts from private.provider_snapshot_jobs'),1);}finally{await db.close()}});
test('same-session command preserves its committed attempt when actual compute SQL raises controlled 57014',async()=>{const db=await setup();try{await db.exec(install);const t=await addTarget(db);await db.exec("create or replace function private.provider_snapshot_compute_payload(p_target jsonb,p_request jsonb,p_component text)returns jsonb language plpgsql stable security invoker set search_path=''set jit=off as $$begin raise exception using errcode='57014',message='synthetic compute deadline';end;$$");
// Keep the real installed-copy contract; change only the expected body of this explicit error fixture.
let def=await scalar(db,"select pg_get_functiondef('private.provider_snapshot_kernel_contract_current()'::regprocedure)");const found=def.match(/\$expected\$([\s\S]*?)\$expected\$::jsonb/);const expected=JSON.parse(found[1]);expected.find(x=>x.signature==='private.provider_snapshot_compute_payload(jsonb,jsonb,text)').body_md5=await scalar(db,"select md5(prosrc)from pg_proc where oid='private.provider_snapshot_compute_payload(jsonb,jsonb,text)'::regprocedure");await db.exec(def.replace(found[1],()=>JSON.stringify(expected)));assert.equal(await scalar(db,'select private.provider_snapshot_kernel_contract_current()'),true);
const q={action:'aggregate',view:'providers',platformId:t.id,startAt:'2026-10-10T18:30:00.000000Z',endAt:'2026-10-11T18:30:00.000000Z',direction:'charge',status:'all',currency:'INR',offset:0,limit:20};await db.query("select private.provider_snapshot_enqueue($1,$2,'orders')",[t,q]);await rejects(db,read('worker-command.sql'),/synthetic compute deadline/);assert.deepEqual((await db.query('select status,attempts from private.provider_snapshot_jobs')).rows,[{status:'running',attempts:1}]);assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_heads'),0);await db.exec(read('worker-command.sql'));assert.equal(await scalar(db,'select attempts from private.provider_snapshot_jobs'),1);}finally{await db.close()}});
test('timely close, two-hour and twenty-four-hour passes remain distinct with their original full-day windows',async()=>{const db=await setup();try{await db.exec(install);await addTarget(db);const r=await scalar(db,'select jsonb_agg(target order by platform_id)from private.provider_snapshot_targets');await db.query("insert into private.provider_snapshot_cohorts(lane,local_date,cutoff,supplement_pass,roster_token,targets,status)values('closed','2026-10-11','2026-10-11T18:30:00Z',2,md5($1::jsonb::text),$1,'ready')",[r]);for(const [pass,at,due]of[[0,'2026-10-12T18:45:00Z','2026-10-12T20:30:00Z'],[1,'2026-10-12T20:31:00Z','2026-10-13T18:30:00Z'],[2,'2026-10-13T18:31:00Z',null]]){await db.exec("update private.provider_snapshot_schedule_state set last_lane='current'");const c=await dispatch(db,at);assert.equal(c.lane,'closed');assert.equal(c.supplementPass,pass);assert.deepEqual(c.coalescedPasses,[]);assert.equal(await scalar(db,'select bool_and(next_due_at is not distinct from $1::timestamptz)from private.provider_snapshot_jobs where id in(select job_id from private.provider_snapshot_cohort_jobs where cohort_id=$2)',[due,c.cohortId]),true);assert.equal(await scalar(db,"select bool_and(window_to-window_from=interval'1day')from private.provider_snapshot_jobs where id in(select job_id from private.provider_snapshot_cohort_jobs where cohort_id=$1)",[c.cohortId]),true);await db.query("update private.provider_snapshot_cohorts set status='ready'where id=$1",[c.cohortId]);}assert.equal(await scalar(db,'select count(*)::int from private.provider_schedule_catchup_audit'),0);}finally{await db.close()}});

async function plannedRequests(db,targets,day,localCutoff){const rows=[];for(const[component,prior]of[['orders',0],['orders',1],['intake',0],['intake',1],['submission',0]])for(const target of targets){const times=(await db.query("select private.provider_snapshot_iso(($1::date-$3::int)::timestamp at time zone'Asia/Kolkata')f,private.provider_snapshot_iso((($2::timestamp)-make_interval(days=>$3::int))at time zone'Asia/Kolkata')e",[day,localCutoff,prior])).rows[0];rows.push({target,component,request:{action:'aggregate',view:'providers',platformId:target.id,startAt:times.f,endAt:times.e,direction:'charge',status:'all',currency:'INR',offset:0,limit:20}});}return rows;}
const jobState=async db=>(await db.query("select to_jsonb(j)-array['id','created_at','updated_at']state from private.provider_snapshot_jobs j order by request_key::text")).rows;
async function originalAdmission(db,plans,closed,due){for(const p of plans){const id=await scalar(db,'select private.provider_snapshot_enqueue($1,$2,$3)',[p.target,p.request,p.component]);if(closed)assert.equal(await scalar(db,'select private.provider_snapshot_requeue($1)',[id]),true);await db.query('update private.provider_snapshot_jobs set next_due_at=$2 where id=$1',[id,due]);}}
test('bulk current admission matches enqueue for existing ready keys and new keys, without resetting attempts or revisions',async()=>{const db=await setup();try{await db.exec(install);const targets=[await addTarget(db,'CURRENT_A'),await addTarget(db,'CURRENT_B')];await noOldDates(db,'2026-10-13T06:37:00Z');const plans=await plannedRequests(db,targets,'2026-10-13','2026-10-13T12:00:00');for(const p of plans.filter(x=>x.target.id===targets[0].id)){const id=await scalar(db,'select private.provider_snapshot_enqueue($1,$2,$3)',[p.target,p.request,p.component]);await db.query("update private.provider_snapshot_jobs set status='ready',revision=5,attempts=3,fence=7,last_error_code='preserve_me'where id=$1",[id]);}await db.exec('begin;savepoint parity');await originalAdmission(db,plans,false,'2026-10-13T07:00:00Z');const expected=await jobState(db);await db.exec('rollback to savepoint parity');const c=await dispatch(db,'2026-10-13T06:37:00Z');assert.equal(c.jobs,10);assert.deepEqual(await jobState(db),expected);assert.equal(await scalar(db,"select count(*)::int from private.provider_snapshot_jobs where status='ready'and revision=5 and attempts=3"),5);await db.exec('rollback');}finally{await db.close()}});
test('bulk closed admission matches enqueue + requeue for mixed existing states, expired leases and new keys',async()=>{const db=await setup();try{await db.exec(install);const targets=[await addTarget(db,'CLOSED_A'),await addTarget(db,'CLOSED_B')];await db.exec("update private.provider_snapshot_schedule_state set last_lane='current'");const plans=await plannedRequests(db,targets,'2026-10-11','2026-10-12T00:00:00');let n=0;for(const p of plans.filter(x=>x.target.id===targets[0].id)){const id=await scalar(db,'select private.provider_snapshot_enqueue($1,$2,$3)',[p.target,p.request,p.component]);await db.query("update private.provider_snapshot_jobs set status=$2,revision=5,attempts=3,fence=7,run_id='00000000-0000-4000-8000-000000000001',worker='old',lease_until='2026-10-01T00:00:00Z',claim_backend_pid=123,claim_backend_start='2026-10-01T00:00:00Z',last_error_code='old'where id=$1",[id,['ready','queued','failed','running','ready'][n++]]);}await db.exec('begin;savepoint parity');await originalAdmission(db,plans,true,null);const expected=await jobState(db);await db.exec('rollback to savepoint parity');const c=await dispatch(db,'2026-10-13T06:37:00Z');assert.equal(c.jobs,10);assert.equal(c.supplementPass,2);assert.deepEqual(await jobState(db),expected);assert.equal(await scalar(db,"select count(*)::int from private.provider_snapshot_jobs where revision=6 and attempts=0 and status='queued'"),5);assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_jobs where revision=2'),5);await db.exec('rollback');}finally{await db.close()}});
test('hot/history quota rejection rolls back planning, audit and all bulk rows; forged targets never enter the plan',async()=>{const db=await setup();try{await db.exec(install);const target=await addTarget(db);await noOldDates(db,'2026-10-13T06:37:00Z');await db.exec("update private.provider_snapshot_storage_usage set jobs=4998 where storage_class='hot'");const before=await scalar(db,'select count(*)::int from private.provider_snapshot_cohorts');await assert.rejects(()=>dispatch(db,'2026-10-13T06:37:00Z'),/snapshot_queue_capacity/);assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_jobs'),0);assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_cohorts'),before);await db.exec("update private.provider_snapshot_storage_usage set jobs=0 where storage_class='hot';update private.provider_snapshot_storage_usage set jobs=49998 where storage_class='history';delete from private.provider_snapshot_cohorts;update private.provider_snapshot_schedule_state set last_lane='current'");await assert.rejects(()=>dispatch(db,'2026-10-13T06:37:00Z'),/snapshot_queue_capacity/);assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_jobs'),0);assert.equal(await scalar(db,'select count(*)::int from private.provider_schedule_catchup_audit'),0);assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_cohorts'),0);await db.query("update private.provider_snapshot_targets set target=target||'{\"currency\":\"USD\"}'where platform_id=$1",[target.id]);assert.equal((await dispatch(db,'2026-10-13T06:37:00Z')).status,'no_verified_targets');await assert.rejects(()=>db.query('select private.provider_snapshot_register_target($1)',[{...target,currency:'USD'}]),/unsupported_snapshot_target/);}finally{await db.close()}});
test('changed shared admission code blocks the building early-return path before any direct update',async()=>{const db=await setup();try{await db.exec(install);await addTarget(db);const c=await dispatch(db,'2026-10-13T06:37:00Z');await db.exec('alter function private.provider_snapshot_requeue(uuid,timestamptz)cost 101');await assert.rejects(()=>dispatch(db,'2026-10-13T06:38:00Z'),/snapshot_admission_contract_changed/);assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_jobs'),c.jobs);assert.equal(await scalar(db,'select status from private.provider_snapshot_cohorts where id=$1',[c.cohortId]),'building');}finally{await db.close()}});
test('all 90 stale ready slots requeue with 18 dependency calls, keep lastgood heads, and use a three-second control budget',async(t)=>{const db=await setup();try{await db.exec(install);for(let i=0;i<18;i++)await addTarget(db,'STALE_'+i);await db.exec("create sequence private.test_dependency_calls;alter function private.provider_snapshot_dependency_token(jsonb)rename to test_dependency_original;create function private.provider_snapshot_dependency_token(p_target jsonb)returns text language plpgsql stable security invoker set search_path=''as $$begin perform nextval('private.test_dependency_calls');return private.test_dependency_original(p_target);end;$$");const when='2026-10-13T06:37:00Z';await noOldDates(db,when);await db.exec("set statement_timeout='3s'");const start=performance.now();const c=await dispatch(db,when);const admissionMs=performance.now()-start;assert.equal(c.jobs,90);assert.equal(Number(await scalar(db,'select last_value from private.test_dependency_calls')),18);await db.exec("insert into private.provider_snapshot_artifacts(job_id,run_id,fence,revision,dependency_token,payload,payload_hash,stored_bytes,provenance,next_due_at)select id,gen_random_uuid(),fence,revision,dependency_token,'{}','synthetic',2,'{}',next_due_at from private.provider_snapshot_jobs;insert into private.provider_snapshot_heads(job_id,snapshot_id)select job_id,id from private.provider_snapshot_artifacts;update private.provider_snapshot_jobs set status='ready',attempts=2;alter function private.dashboard_data_group(text,text)cost 101;select setval('private.test_dependency_calls',1,false)");const heads=(await db.query('select *from private.provider_snapshot_heads order by job_id')).rows;const requeueStart=performance.now();const again=await dispatch(db,when);const requeueMs=performance.now()-requeueStart;assert.equal(again.status,'building');assert.equal(again.cohortId,c.cohortId);assert.equal(Number(await scalar(db,'select last_value from private.test_dependency_calls')),18);assert.equal(await scalar(db,"select count(*)::int from private.provider_snapshot_jobs where status='queued'and revision=2 and attempts=0"),90);assert.deepEqual((await db.query('select *from private.provider_snapshot_heads order by job_id')).rows,heads);t.diagnostic(JSON.stringify({syntheticOnly:true,componentCount:90,targets:18,tokenCallsPerTick:18,statementTimeout:'3s',admissionMs,requeueMs}));}finally{await db.close()}});
test('ordered admission preserves failed-quota trigger semantics when retry precedes or follows a new key',async()=>{for(const first of[true,false]){const db=await setup();try{await db.exec(install);const t=await addTarget(db);await db.exec("update private.provider_snapshot_schedule_state set last_lane='current'");const plans=await plannedRequests(db,[t],'2026-10-11','2026-10-12T00:00:00');const p=plans[first?0:4];const id=await scalar(db,'select private.provider_snapshot_enqueue($1,$2,$3)',[p.target,p.request,p.component]);await db.query("update private.provider_snapshot_jobs set status='failed',attempts=3 where id=$1",[id]);await db.exec("update private.provider_snapshot_storage_usage set failed_jobs=500 where storage_class='history';begin;savepoint parity");if(first){await originalAdmission(db,plans,true,null);const expected=await jobState(db);const usage=(await db.query('select *from private.provider_snapshot_storage_usage order by storage_class')).rows;await db.exec('rollback to savepoint parity');await dispatch(db,'2026-10-13T06:37:00Z');assert.deepEqual(await jobState(db),expected);assert.deepEqual((await db.query('select *from private.provider_snapshot_storage_usage order by storage_class')).rows,usage);}else{await assert.rejects(()=>originalAdmission(db,plans,true,null),/snapshot_queue_capacity/);await db.exec('rollback to savepoint parity');await assert.rejects(()=>dispatch(db,'2026-10-13T06:37:00Z'),/snapshot_queue_capacity/);await db.exec('rollback to savepoint parity');assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_jobs'),1);assert.equal(await scalar(db,'select count(*)::int from private.provider_schedule_catchup_audit'),0);}await db.exec('rollback');}finally{await db.close()}}});
test('a failed two-hour pass is not bypassed at twenty-four hours, and an overdue running cohort is not preempted',async()=>{const db=await setup();try{await db.exec(install);await addTarget(db);const r=await scalar(db,'select jsonb_agg(target order by platform_id)from private.provider_snapshot_targets');await db.query("insert into private.provider_snapshot_cohorts(lane,local_date,cutoff,supplement_pass,roster_token,targets,status)values('closed','2026-10-12','2026-10-12T18:30:00Z',1,md5($1::jsonb::text),$1,'failed')",[r]);await db.exec("update private.provider_snapshot_schedule_state set last_lane='current'");const c=await dispatch(db,'2026-10-14T06:37:00Z');assert.equal(c.lane,'closed');assert.equal(await scalar(db,'select local_date::text from private.provider_snapshot_cohorts where id=$1',[c.cohortId]),'2026-10-13');assert.equal(await scalar(db,"select count(*)::int from private.provider_snapshot_cohorts where local_date='2026-10-12'and supplement_pass=2"),0);const later=await dispatch(db,'2026-10-15T06:37:00Z');assert.equal(later.cohortId,c.cohortId);assert.equal(later.status,'building');assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_cohorts'),2);}finally{await db.close()}});
test('inactive definitions still require their previously started runs to drain before rollback',async()=>{const db=await setup();try{await db.exec(install);await db.exec("insert into cron.job_run_details(jobid,database,username,status)select jobid,current_database(),current_user,'running'from cron.job where jobname='provider-snapshot-worker-v1'");await rejects(db,rollback,/snapshot_cron_run_not_drained/);assert.equal(await scalar(db,'select count(*)::int from cron.job'),3);await db.exec("update cron.job_run_details set status='failed',end_time=clock_timestamp();select cron.schedule('unrelated-active','1 second','select 1');insert into cron.job_run_details(jobid,database,username,status)select jobid,current_database(),current_user,'running'from cron.job where jobname='unrelated-active'");await db.exec(rollback);assert.equal(await scalar(db,'select jobname from cron.job'),'unrelated-active');assert.equal(await scalar(db,'select count(*)::int from cron.job_run_details'),2);}finally{await db.close()}});
test('matching native but unsupported maintenance roster is rejected by the original canonical validator without writes',async()=>{const db=await setup();try{await db.exec(install);await db.exec("insert into public.ar_config_targets values('AR','BR','SYNTHETIC_BR','BRL','巴西','America/Sao_Paulo');insert into public.dashboard_platform_team_map values('AR','BR','SYNTHETIC_BR','Synthetic BR','Synthetic team','BR','巴西',true)");const target=await scalar(db,"select to_jsonb(t)from private.provider_snapshot_native_catalog()t where source_name='SYNTHETIC_BR'");await db.query('insert into private.provider_snapshot_targets(platform_id,target,enabled)values($1,$2,true)',[target.id,target]);assert.equal(await scalar(db,'select private.provider_snapshot_target_current($1)',[target]),true);const q={action:'aggregate',view:'providers',platformId:target.id,startAt:'2026-10-13T03:00:00.000000Z',endAt:'2026-10-13T06:30:00.000000Z',direction:'charge',status:'all',currency:'INR',offset:0,limit:20};for(const run of[()=>db.query("select private.provider_snapshot_enqueue($1,$2,'orders')",[target,q]),()=>dispatch(db,'2026-10-13T06:37:00Z')])await assert.rejects(run,e=>e.code==='22023'&&e.message==='unsupported_snapshot_target');assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_jobs'),0);assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_cohorts'),0);assert.equal(await scalar(db,'select count(*)::int from private.provider_schedule_catchup_audit'),0);await db.exec('alter function private.provider_snapshot_target(jsonb)cost 101');await assert.rejects(()=>dispatch(db,'2026-10-13T06:37:00Z'),/snapshot_admission_contract_changed/);}finally{await db.close()}});
test('managed cron owner permits SELECT and scheduling APIs but rejects direct table locks; API-only installer remains atomic',async()=>{const db=await setup();try{
// PGlite's bootstrap postgres cannot be demoted. Use an explicitly named non-superuser
// inheriting only the original application's owner privileges; no cron-owner membership.
await db.exec(install);await db.exec(rollback);
await db.exec("create role test_cron_owner;create role test_managed_postgres nosuperuser inherit;grant postgres to test_managed_postgres;alter table cron.job owner to test_cron_owner;alter table cron.job_run_details owner to test_cron_owner;alter table cron.job alter column username set default current_setting('role');revoke all on cron.job,cron.job_run_details from postgres;grant select on cron.job to test_managed_postgres;grant select,delete on cron.job_run_details to test_managed_postgres;alter function cron.schedule(text,text,text)owner to test_cron_owner;alter function cron.schedule(text,text,text)security definer;alter function cron.alter_job(bigint,text,text,text,text,boolean)owner to test_cron_owner;alter function cron.alter_job(bigint,text,text,text,text,boolean)security definer;alter function cron.unschedule(bigint)owner to test_cron_owner;alter function cron.unschedule(bigint)security definer;grant usage on schema cron to test_cron_owner;set role test_managed_postgres");
assert.equal(await scalar(db,"select rolsuper from pg_roles where rolname=current_user"),false);assert.equal(await scalar(db,"select has_table_privilege(current_user,'cron.job','SELECT')"),true);assert.equal(await scalar(db,"select has_table_privilege(current_user,'cron.job','UPDATE')"),false);
await rejects(db,'begin;lock table cron.job in share row exclusive mode nowait;',e=>e.code==='42501');await assert.rejects(()=>db.exec("insert into cron.job(jobname,schedule,command)values('denied','1 second','select 1')"),e=>e.code==='42501');
assert.match(rawInstall,/BEGIN ISOLATION LEVEL SERIALIZABLE;/);assert.doesNotMatch(rawInstall,/lock table cron\.job\b/i);assert.doesNotMatch(rawRollback,/lock table cron\.job\b/i);
// Adapt ONLY the fixture caller's name; full real metadata/collision/atomicity guards remain.
const managedInstall=install.replace("current_user<>'postgres'","current_user<>'test_managed_postgres'"),managedRollback=rollback.replace("current_user<>'postgres'","current_user<>'test_managed_postgres'");
await db.exec(managedInstall);assert.equal(await scalar(db,"select count(*)::int from cron.job where not active and username=current_user"),3);await db.exec(managedRollback);assert.equal(await scalar(db,'select count(*)::int from cron.job'),0);
await db.exec("select set_config('test.serialize_schedule','provider-snapshot-dispatch-v1',false)");await rejects(db,managedInstall,e=>e.code==='40001');assert.equal(await scalar(db,'select count(*)::int from cron.job'),0);assert.equal(await scalar(db,"select md5(prosrc)from pg_proc where oid='private.provider_snapshot_dispatch(timestamptz,integer)'::regprocedure"),'7d123f5838e7c67ccf374ccf17a88e93');
}finally{await db.close()}});
test('installer refuses an outer read-committed transaction after its snapshot or a missing serializable setting',async()=>{const db=await setup();try{await db.exec('begin;select 1');await rejects(db,install,e=>e.code==='25001');assert.equal(await scalar(db,'select count(*)::int from cron.job'),0);const wrong=install.replace('BEGIN ISOLATION LEVEL SERIALIZABLE;\nSET TRANSACTION ISOLATION LEVEL SERIALIZABLE;','BEGIN ISOLATION LEVEL READ COMMITTED;');await rejects(db,wrong,/snapshot_cron_isolation_required/);assert.equal(await scalar(db,'select count(*)::int from cron.job'),0);}finally{await db.close()}});
test('existing owner/database drift and unexpected API default database fail closed without overwriting definitions',async()=>{const db=await setup();try{await db.exec(install);for(const column of['username','database']){await db.exec(`update cron.job set ${column}='wrong_identity'where jobname='provider-snapshot-worker-v1'`);await rejects(db,install,/snapshot_cron_job_drift/);await rejects(db,rollback,/snapshot_cron_job_drift/);assert.equal(await scalar(db,`select ${column} from cron.job where jobname='provider-snapshot-worker-v1'`),'wrong_identity');await db.exec(`update cron.job set ${column}=${column==='username'?'current_user':'current_database()'} where jobname='provider-snapshot-worker-v1'`);}await db.exec(rollback);await db.exec("alter table cron.job alter column database set default 'unexpected_api_database'");await rejects(db,install,/snapshot_cron_job_drift/);assert.equal(await scalar(db,'select count(*)::int from cron.job'),0);assert.equal(await scalar(db,"select md5(prosrc)from pg_proc where oid='private.provider_snapshot_dispatch(timestamptz,integer)'::regprocedure"),'7d123f5838e7c67ccf374ccf17a88e93');}finally{await db.close()}});
